item.aggregated_output:
 1	module broken_fragment_top #(
 2	  parameter int unsigned W = 12
 3	) (
 4	  input logic clk_i,
 5	  input logic rst_ni,
 6	  input logic [W-1:0] data_i,
 7	  output logic [3:0] narrow_o,
 8	  output logic invalid_member_o,
 9	  output logic [W-1:0] external_o
10	);
11	  typedef struct packed {
12	    logic [W-1:0] payload;
13	    logic valid;
14	  } sample_t;
15	
16	  sample_t sample;
17	  logic [3:0] narrow_q;
18	
19	  assign sample.payload = data_i;
20	  assign sample.valid = 1'b1;
21	  assign invalid_member_o = sample.missing;
22	  assign narrow_o = narrow_q;
23	
24	  always_ff @(posedge clk_i) begin
25	    if (!rst_ni)
26	      narrow_q <= '0;
27	    else
28	      narrow_q <= data_i;
29	  end
30	
31	  external_stage #(.W(W)) u_external (
32	    .clk_i(clk_i),
33	    .data_i(data_i),
34	    .data_o(external_o)
35	  );
36	endmodule
